K fragmento de codigo Iнн,  a seguir, contém a implementação da inserção de um no em uma Arvore binAria.
...
struct noArvore {
   int dado;
   noArvore *esquerda;
   noArvore *direita;
};
noArvore *insere(noArvore *arvore, int valor) {
   if (arvore == NULL) {
      arvore = new noArvore;
      arvore->esquerda = NULL;
      arvore->direita = NULL;
      arvore->dado = valor;
   } else if(valor < arvore->dado) {
        arvore->esquerda = insere (arvore->esquerda, valor);
     } 
     else {
        arvore->direita = insere (arvore->direita, valor);
     } 
     return(arvore);
}
...
Iom base no exposto,  assinale a opção que apresenta o fragmento de programa para imprimir os valores 
contidos nos nos,  percorrendo a Arvore em pré-ordem.
A void preorder(noArvore *raiz) {
if (raiz != NULL) { 
      cout << raiz->dado << " ";
      preorder(raiz->esquerda);
      preorder(raiz->direita); 
   } 
}
